import { Routes } from '@angular/router';
import { RoutePath } from './route-paths';
import { HomePage } from './home/home.page';
import { LoginPage } from './login/login.page';
import { ProfilePage } from './profile/profile.page';
import { ReportsPage } from './admin/reports.page';
import { authGuard, guestGuard } from './guards/auth.guard';
import { nativeOnlyGuard } from './guards/native-only.guard';
import { adminChildGuard } from './guards/admin-child.guard';

export const routes: Routes = [
  { path: '', pathMatch: 'full', redirectTo: 'home' },
  { path: 'home', component: HomePage },
  {
    path: 'login',
    canActivate: [guestGuard],
    component: LoginPage,
  },
  { path: 'profile', canActivate: [authGuard], component: ProfilePage },
  { path: RoutePath.Home + '-start', component: HomePage },
  {
    path: RoutePath.Upload,
    canMatch: [nativeOnlyGuard],
    canActivate: [authGuard],
    loadChildren: () => import('./upload/upload.routes').then((m) => m.UPLOAD_ROUTES),
  },
  {
    path: RoutePath.Admin,
    canActivateChild: [adminChildGuard],
    children: [
      { path: 'reports', component: ReportsPage },
      { path: 'audit', loadComponent: () => import('./admin/audit.page').then((c) => c.AuditPage) },
    ],
  },
  { path: RoutePath.Login, component: LoginPage },
  { path: RoutePath.Archive, redirectTo: RoutePath.Home },
  { path: '**', redirectTo: 'home' },
];

